.pdl-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pdl-root,.pdl-root *,.pdl-root *::before,.pdl-root *::after{box-sizing:border-box}
.pdl-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pdl-root img{display:block;border:0;max-width:none}
.pdl-root > [data-node-id]{will-change:transform}
.pdl-root [hidden]{display:none!important}
.pdl-root [data-sh-theme="dark"]{display:none!important}
.pdl-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.pdl-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.pdl-root .n3286_4900{align-content:stretch;display:flex;flex-direction:column;gap:7px;align-items:flex-start;position:relative;flex-shrink:0;width:100%}
.pdl-root .n3286_4901{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:24px;min-width:100%;font-style:normal;position:relative;flex-shrink:0;font-size:20px;color:var(--wa-text-sub, #2d2e38);letter-spacing:-0.4px;width:min-content;white-space:nowrap}
.pdl-root .n3286_4940{align-content:stretch;display:flex;flex-direction:column;height:50px;align-items:flex-start;position:relative;flex-shrink:0;width:408px}
.pdl-root .n3286_4903{background-color:var(--wa-bg, #fff);align-content:stretch;display:flex;gap:10px;height:50px;align-items:center;padding-left:17px;padding-right:17px;padding-top:14px;padding-bottom:14px;position:relative;border-radius:10px;flex-shrink:0;width:408px}
.pdl-root .n3286_4903::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #bfc8db);border-radius:10px;pointer-events:none}
.pdl-root .n3286_4904{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:21px;font-style:normal;position:relative;flex-shrink:0;font-size:18px;color:var(--wa-point, #0058a7);white-space:nowrap;width:52px}
.pdl-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.pdl-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.pdl-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > div{background:linear-gradient(180deg,var(--wa-bg, #0d1117) 0%,var(--wa-bg, #111821) 100%)!important}
.pdl-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > img{opacity:.04!important;filter:invert(1)}
.pdl-root[data-theme="dark"] [data-name="Stage/3D Scene"] img{filter:brightness(.9) saturate(.95) contrast(1.03)}
.pdl-root[data-theme="dark"] [data-name="Stage/Building Image"] img{filter:brightness(.86) contrast(1.04)}
.pdl-root[data-theme="dark"] [data-name="Side Rail"],.pdl-root[data-theme="dark"] [data-name="Filter Panel"] [data-name="Rectangle 4"]{background:color-mix(in srgb, var(--wa-bg, rgb(20 23 29)) 84%, transparent)!important;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 12px 28px rgba(0,0,0,.35)!important;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.pdl-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Background"],.pdl-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Header Background"]{background:var(--wa-bg, #12151b)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.07)!important}
.pdl-root[data-theme="dark"] svg [fill="#FCFCFC"]:not(mask *),.pdl-root[data-theme="dark"] svg [fill="#fcfcfc"]:not(mask *),.pdl-root[data-theme="dark"] svg [fill="white"]:not(mask *),.pdl-root[data-theme="dark"] svg [fill="#F9F9F9"]:not(mask *){fill:var(--wa-surface, #15181e)}
.pdl-root[data-theme="dark"] svg [stroke="#F1F1F1"]:not(mask *),.pdl-root[data-theme="dark"] svg [stroke="#f1f1f1"]:not(mask *),.pdl-root[data-theme="dark"] svg [fill="#F1F1F1"]:not(mask *){stroke:var(--wa-line, #2a2e36)}
.pdl-root[data-theme="dark"] svg path[fill="#F1F1F1"]:not(mask *){fill:var(--wa-surface, #2a2e36)}
.pdl-root[data-theme="dark"] [data-name="Event Log"] [data-name^="Row/"]:hover,.pdl-root[data-theme="dark"] [data-name="Event Log"] [data-name="grid-row"]:hover{filter:brightness(1.15)}
.pdl-root[data-theme="dark"] [data-name="Tooltip Group"] [data-name^="Tooltip/"] p{color:var(--wa-text, #e6ebf2)!important}
.pdl-root[data-theme="dark"] [data-name^="Category/"] img{content:normal!important}
.pdl-root[data-theme="dark"] .n3286_4901{color:var(--wa-text, #eceef2)}
.pdl-root[data-theme="dark"] .n3286_4903{background-color:var(--wa-surface, #171a20)}
.pdl-root[data-theme="dark"] .n3286_4903::after{border-color:var(--wa-line, #3b4250)}
.pdl-root[data-theme="dark"] .n3286_4904{color:var(--wa-point, #7aa7ff)}
